import{_ as a}from"./chunks/L0C2UB_Function_Combination_950.c9MFMRnd.js";import{_ as n,o as p,a as t,b as l}from"./app.BGziXukh.js";const c="/ascendc.github.io/assets/sidstoremode_config.i0YMROOz.png",f=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"矩阵计算（ISASI）","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_ISASI"},{"text":"矩阵计算的搬出","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_store/cube_compute_store"},{"text":"DataCopy（L0C到UB数据搬运）","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_store/DataCopy_L0CToUB"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_store/DataCopy_L0CToUB.md","filePath":"api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_store/DataCopy_L0CToUB.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"数据类型","slug":"数据类型","link":"#数据类型"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1795069053000}'),e={name:"api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_store/DataCopy_L0CToUB.md"};function d(r,s,o,i,_,h){return p(),t("div",null,[...s[0]||(s[0]=[l('<div><article class="markdown-body"><h1>DataCopy（L0C到UB数据搬运）<span id="ZH-CN_TOPIC_0000002382867725"></span></h1><h2 id="产品支持情况">产品支持情况<span id="section1550532418810"></span><a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR&amp;950DT系列产品：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3系列产品：不支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2系列产品：不支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas推理系列产品AI Core：支持</li></ul></div><div data-filter="310p"><ul><li>Atlas推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas训练系列产品：不支持</li></ul></div><h2 id="功能说明">功能说明<span id="section474617392321"></span><a class="header-anchor" href="#功能说明">​</a></h2><p>头文件路径为：<code>&quot;basic_api/kernel_operator_data_copy_intf.h&quot;</code>。</p><p>矩阵计算的结果存放在L0C Buffer，DataCopy接口用于将结果搬运至Unified Buffer（UB）中，并且在搬运过程中支持随路量化等操作。</p><div data-filter="950"><p>以Ascend 950PR&amp;950DT系列产品为例，下图展示了随路量化、随路ReLU、随路通道合并的有效组合、中间数据类型和数据路径。下图中的F32-&gt;F16与F32-&gt;BF16为非量化模式，仅为Cast，其余为随路scalar/tensor量化模式。</p><p><strong>图1</strong> DataCopy L0C Buffer到UB数据搬运随路功能支持情况</p><p><img src="'+a+`" alt></p></div><h2 id="函数原型">函数原型<span id="section1954364615315"></span><a class="header-anchor" href="#函数原型">​</a></h2><div data-filter="950"><p>针对Ascend 950PR&amp;950DT系列产品，DataCopy矩阵搬出接口支持多种随路能力的组合，需要设置不同的寄存器，配合数据搬运指令开启不同的数据搬运能力，对应的接口如下：</p><ul><li><p>数据搬运接口，通路L0C Buffer-&gt;UB，配合设置寄存器实现量化和ReLU激活，矩阵分型格式的转换，函数原型为：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">T</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">U</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">DataCopy</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">U</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">src</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">DataCopyCO12DstParams</span><span class="o">&amp;</span><span class="w"> </span><span class="n">intriParams</span><span class="p">)</span>
</code></pre></div></li><li><p><a href="../cube_store_aux_config/SetFixPipeConfig.html">SetFixPipeConfig</a>：寄存器设置接口，通过调用该接口设置Vector随路量化，其中tensor的每个元素都代表一个量化参数，启用tensor量化时需要设置。</p></li><li><p><a href="../cube_store_aux_config/SetFixpipePreQuantFlag.html">SetFixpipePreQuantFlag</a>：寄存器设置接口，通过调用该接口设置Scalar随路量化参数，此元素代表整个输出矩阵使用的量化参数，启用Scalar量化时需要设置。</p></li><li><p><a href="../cube_store_aux_config/SetFixpipeNz2ndFlag.html">SetFixpipeNz2ndFlag</a>：寄存器设置接口，通过调用该接口设置随路<a href="../cube_store_key_features/NZ2ND.html">Nz2ND</a>格式转换配置，使用随路Nz2ND需要设置。</p></li><li><p><a href="../cube_store_aux_config/SetFixpipeNz2dnFlag.html">SetFixpipeNz2dnFlag</a>：寄存器设置接口，通过调用该接口设置随路<a href="../cube_store_key_features/NZ2DN.html">Nz2DN</a>格式转换配置，使用随路Nz2DN需要设置。</p></li></ul></div><div data-filter="310p"><p>针对Atlas推理系列产品AI Core，支持的函数原型如下：</p><ul><li><p>Local Memory -&gt; Local Memory</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">T</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">DataCopy</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">src</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">DataCopyParams</span><span class="o">&amp;</span><span class="w"> </span><span class="n">intriParams</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">DataCopyEnhancedParams</span><span class="o">&amp;</span><span class="w"> </span><span class="n">enhancedParams</span><span class="p">)</span>
</code></pre></div></li><li><p>Local Memory -&gt; Local Memory，支持源操作数和目的操作数类型不一致。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">T</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">U</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">DataCopy</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">U</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">src</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">DataCopyParams</span><span class="o">&amp;</span><span class="w"> </span><span class="n">intriParams</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">DataCopyEnhancedParams</span><span class="o">&amp;</span><span class="w"> </span><span class="n">enhancedParams</span><span class="p">)</span>
</code></pre></div></li></ul></div><h2 id="参数说明">参数说明<span id="section1592117358563"></span><a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 模板参数说明</p><table><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>T</td><td>目的操作数的数据类型。支持的数据类型请参考<a href="#section8664371012">数据类型</a>。</td></tr><tr><td>U</td><td>源操作数的数据类型。支持的数据类型请参考<a href="#section8664371012">数据类型</a>。</td></tr></tbody></table><div data-filter="950"><p><strong>表2</strong> 参数说明（<a href="../../../../../guide/programming_guide/language_extension/simd_builtin_keywords.html">NPU架构版本3510</a>）</p><table><thead><tr><th>参数名称</th><th>输入/输出</th><th>含义</th></tr></thead><tbody><tr><td>dst</td><td>输出</td><td>目的操作数，类型为LocalTensor，物理位置为UB（TPosition为VECIN、VECOUT或VECCALC），数据格式为Nz、ND或DN，地址需要满足32字节对齐。</td></tr><tr><td>src</td><td>输入</td><td>源操作数，类型为LocalTensor，物理位置为L0C Buffer（TPosition为CO1），通常为Mmad接口计算的结果。数据格式为Nz，地址需要满足64字节对齐。</td></tr><tr><td>intriParams</td><td>输入</td><td>搬运参数，类型为<a href="#zh-cn_topic_0000002542828493_table35908519282">DataCopyCO12DstParams</a>。 <br>具体定义请参考<code>\${INSTALL_DIR}/asc/include/basic_api/kernel_struct_data_copy.h</code>，<code>\${INSTALL_DIR}</code>请替换为CANN软件安装后文件存储路径。</td></tr></tbody></table><p><strong>表3</strong> DataCopyCO12DstParams结构体参数定义（<a href="../../../../../guide/programming_guide/language_extension/simd_builtin_keywords.html">NPU架构版本3510</a>）<a id="zh-cn_topic_0000002542828493_table35908519282"></a></p><table><thead><tr><th>参数名称</th><th>含义</th></tr></thead><tbody><tr><td>sid</td><td>此参数用户无需关注，设置为0即可。</td></tr><tr><td>nSize</td><td>源Nz矩阵在N方向上的大小。取值范围nSize∈[0, 4095]，nSize必须为16的倍数。<br><strong>注：nSize=0表示不执行搬运，该接口将被视为NOP（空操作）。</strong></td></tr><tr><td>mSize</td><td>源Nz矩阵在M方向上的大小，取值范围为mSize∈[0, 65535]。若开启Nz2DN，mSize*sizeof(T)必须为32的倍数。<br><strong>注：mSize=0表示不执行搬运，该接口将被视为NOP（空操作）。</strong></td></tr><tr><td>dstStride</td><td>•不开启Nz2ND功能（<a href="../cube_store_key_features/NZ2NZ.html">Nz2Nz搬运</a>）：目的Nz矩阵中相邻Z排布的起始地址偏移，取值不为0，单位为datablock（32字节）。<br>•开启随路<a href="../cube_store_key_features/NZ2ND.html">Nz2ND</a>功能：目的ND矩阵每一行中的元素个数，取值不为0 ，单位为element。</td></tr><tr><td>srcStride</td><td>源Nz矩阵中相邻Z排布的起始地址偏移，取值范围为srcStride∈[0, 65535]，单位为C0_Size（16*sizeof(T)），T为src的数据类型，其值应填成mSize对16向上取整。</td></tr><tr><td>unitFlag</td><td>unitFlag是一种Mmad指令和Fixpipe指令细粒度的并行，开启该功能后，硬件每计算完一个分形，计算结果就会被搬出。取值说明如下：<br>  • 0（2&#39;b00）：不开启unitFlag。<br>  • 2（2&#39;b10）：开启unitFlag，硬件执行完指令之后，不复位单元标记位。<br>  • 3（2&#39;b11）：开启unitFlag，硬件执行完指令之后，复位单元标记位。<br>开启该功能时，须将Mmad指令和Fixpipe指令的unitFlag值设置为2或3。<br>参数设置方案和特性细节可参考：Mmad计算中关键特性说明的<a href="../mmad_compute_key_features/UnitFlag.html">UnitFlag</a>章节。</td></tr><tr><td>quantPre</td><td>用于控制量化模式，QuantMode_t类型，具体定义如下：<br>  • float/int32_t输出此需配置为QuantMode_t::NoQuant。<br>  • half/bfloat16_t输出，此参数需配置为QuantMode_t::F322F16/QuantMode_t::F322BF16。<br>  • 配置为scalar量化时，需要调用<a href="../cube_store_aux_config/SetFixpipePreQuantFlag.html">SetFixpipePreQuantFlag</a>接口来设置scalar量化参数。<br>  • 配置为tensor量化时，需要调用<a href="../cube_store_aux_config/SetFixPipeConfig.html">SetFixPipeConfig</a>来设置tensor量化参数，其中tensor量化参数需要通过DataCopy从L1 Buffer搬运至Fixpipe Buffer。<br>注：此参数需要用户手动配置，不会自动推导配置对应量化模式。<br>enum QuantMode_t<br>{<br> NoQuant, // 不开启量化功能<br> F322F16, // Float32_2_Float16: float cast成half，cast mode为CAST_RINT模式<br> F322BF16, // Float32_2_BFloat16 :float cast成bfloat16_t，cast mode为CAST_RINT模式<br> DEQF16, // DeQuant_Float16: int32_t量化成half, scalar量化<br> VDEQF16, // Vector_DeQuant_Float16: int32_t量化成half，tensor量化<br> QF322B8_PRE, // Quant_Float32_2_B8: float量化成int8_t/uint8_t，scalar量化<br> VQF322B8_PRE, // Vector_Quant_Float32_2_B8: float量化成int8_t/uint8_t，tensor量化<br> REQ8, // ReQuant_int8: int32_t量化成int8_t/uint8_t，scalar量化<br> VREQ8, // Vector_ReQuant_int8: int32_t量化成int8_t/uint8_t，tensor量化<br> QF322FP8_PRE, // Quant_Float32_2_FP8: float量化成fp8_e4m3fn_t，scalar量化<br> VQF322FP8_PRE, // Vector_Quant_Float32_2_FP8: float量化成fp8_e4m3fn_t，tensor量化<br> QF322HIF8_PRE, // Quant_Float32_2_HIF8: float量化成hifloat8_t(Half to Away Round)，scalar量化<br> VQF322HIF8_PRE, // Vector_Quant_Float32_2_HIF8: float量化成hifloat8_t(Half to Away Round)，tensor量化<br> QF322HIF8_PRE_HYBRID, // Quant_Float32_2_HIF8_Hybrid: float量化成hifloat8_t(Hybrid Round)，scalar量化<br> VQF322HIF8_PRE_HYBRID, // Vector_Quant_Float32_2_HIF8_Hybrid: float量化成hifloat8_t(Hybrid Round)，tensor量化<br> QS322BF16_PRE, // Quant_Int32_2_BFloat16: int32_t量化成bfloat16_t，scalar量化<br> VQS322BF16_PRE, // Vector_Quant_Int32_2_BFloat16: int32_t量化成bfloat16_t，tensor量化<br> QF322F16_PRE, // Quant_Float32_2_Float16: float量化成half，scalar量化<br> VQF322F16_PRE, // Vector_Quant_Float32_2_Float16: float量化成half，tensor量化<br> QF322BF16_PRE, // Quant_Float32_2_BFloat16: float量化成bfloat16_t，scalar量化<br> VQF322BF16_PRE, // Vector_Quant_Float32_2_BFloat16: float量化成bfloat16_t，tensor量化<br> QF322F32_PRE, // Quant_Float32_2_Float32: float量化成float，scalar量化，精度可以达到双千分之一，无法达到双万分之一。如果有双万分之一的精度要求，建议使用<a href="../../../adv_api/quantization/AscendDequant.html">AscendDeQuant</a>高阶API。<br> VQF322F32_PRE, // Vector_Quant_Float32_2_Float32: float量化成float，tensor量化，精度可以达到双千分之一，无法达到双万分之一。如果有双万分之一的精度要求，建议使用<a href="../../../adv_api/quantization/AscendDequant.html">AscendDeQuant</a>高阶API。<br>};</td></tr><tr><td>reluPre</td><td>用于配置ReLU操作的模式，类型为uint8_t，取值如下：<br>  • 0：不开启ReLU；<br>  • 1：Normal ReLU。</td></tr><tr><td>channelSplit</td><td>类型为bool，默认值为false。本通路不支持Channel Split，保持默认值即可。</td></tr><tr><td>nz2ndEn</td><td>类型为bool，配置是否开启Nz2ND的格式转换。<br>如果要开启Nz2ND的功能需要同步调用<a href="../cube_store_aux_config/SetFixpipeNz2ndFlag.html">SetFixpipeNz2ndFlag</a>来设置格式转换的相关配置信息。<br>  • false：不开启；<br>  • true：开启。</td></tr><tr><td>dualDstCtl</td><td>双目标模式控制参数。对于Ascend 950PR&amp;950DT系列产品，同一AI Core内有一个Cube Core和两个Vector Core，当启用双目标模式控制时，L0C Buffer中的M×N矩阵将被分成两半，并同时分别写入两个Vector Core各自的UB中，其中前半部分写入SUB BLOCK0，后半部分写入SUB BLOCK1。<br>  • 2&#39;b00：单目标模式，将整个矩阵写入通过subBlockId参数配置的目标UB。<br>  • 2&#39;b01：双目标模式，按M维度拆分成形状为M / 2 * N的两个矩阵，分别写入两个UB, M必须为2的倍数。<br>  • 2&#39;b10：双目标模式，按N维度拆分成形状为M * N / 2的两个矩阵，分别写入两个UB, N须为32的倍数。<br>  • 2&#39;b11：保留值。<br>dualDstCtl仅支持在普通搬运模式（Nz2Nz）或Nz2ND搬运场景下使用，不支持随路功能场景。<br>参数设置方案和特性细节可参考：<a href="../cube_store_key_features/L0C_to_UB_dual_target_mode.html">L0C到UB双目标模式</a></td></tr><tr><td>subBlockId</td><td>启用单目标模式时用于指示目标UB的SUB BLOCK ID。取值为0或1，取值为0时写入SUB BLOCK0，为1时写入SUB BLOCK1，默认为0。</td></tr><tr><td>nz2dnEn</td><td>类型为bool，配置是否开启Nz2DN的格式转换。<br>如果要开启Nz2DN的功能需要同步调用<a href="../cube_store_aux_config/SetFixpipeNz2dnFlag.html">SetFixpipeNz2dnFlag</a>来设置格式转换的相关配置信息。<br>  • false：不开启；<br>  • true：开启。</td></tr></tbody></table></div><div data-filter="310p"><p><strong>表4</strong> 参数说明（<a href="../../../../../guide/programming_guide/language_extension/simd_builtin_keywords.html">NPU架构版本2002</a>）</p><table><thead><tr><th>参数名称</th><th>输入/输出</th><th>含义</th></tr></thead><tbody><tr><td>dst</td><td>输出</td><td>目的操作数，类型为LocalTensor。</td></tr><tr><td>src</td><td>输入</td><td>源操作数，类型为LocalTensor。</td></tr><tr><td>intriParams</td><td>输入</td><td>搬运参数。DataCopyParams类型。</td></tr><tr><td>enhancedParams</td><td>输入</td><td>增强信息参数。DataCopyEnhancedParams类型。<br>具体定义请参考<code>\${INSTALL_DIR}/asc/include/basic_api/kernel_struct_data_copy.h</code>，<code>\${INSTALL_DIR}</code>请替换为CANN软件安装后文件存储路径。</td></tr></tbody></table><p><strong>表5</strong> DataCopyEnhancedParams结构参数说明（<a href="../../../../../guide/programming_guide/language_extension/simd_builtin_keywords.html">NPU架构版本2002</a>）</p><table><thead><tr><th>参数名称</th><th>含义</th></tr></thead><tbody><tr><td>blockMode</td><td>数据搬运基本分形，BlockMode枚举类型，支持以下配置：<br>  • BLOCK_MODE_NORMAL：表示传输单位为32字节。当前暂不支持。<br>  • BLOCK_MODE_MATRIX：表示传输单位为一个16 * 16的cube分形。<br>  • BLOCK_MODE_VECTOR：表示传输单位为一个1 * 16的cube分形。<br>  • BLOCK_MODE_SMALL_CHANNEL：表示传输单位为一个16 * 4的cube分形。当前暂不支持。<br>  • BLOCK_MODE_DEPTHWISE：表示传输单位为一个16 * 16的cube分形，提供随路channel-split功能。当前暂不支持。<br>每种模式下对应的blockLen等参数单位见<a href="#table13396838183618">表6</a>。</td></tr><tr><td>deqScale</td><td>随路精度转换辅助参数，即量化模式，支持的量化模式取值和对应的数据类型等信息请参考<a href="#table168091348673">表7</a>。其中DEQ、DEQ8、DEQ16模式，需要传入deqValue量化系数，设置deqValue的对应比特位；VDEQ、VDEQ8、VDEQ16模式，需要传入包含16个元素（deqValue）的量化参数向量，设置deqTensorAddr的对应比特位，同时保证DEQADDR中存储的反量化参数向量的每个元素（deqValue）都符合预期和使用限制。<br>VDEQ模式下，反量化参数向量长度为32字节（16个half元素）；其他模式下，反量化参数向量长度为128字节（16个64bit的反量化元素）。</td></tr><tr><td>deqValue</td><td>量化系数。 deqValue的配置方式请参考<a href="#table54451538192912">deqValue配置方式</a>。</td></tr><tr><td>deqTensorAddr</td><td>Unified Buffer（UB）中存储反量化参数向量的起始地址。deqScale为VDEQ/VDEQ8/VDEQ16模式时，需要传入反量化运算时的参数向量的地址。该地址要满足32字节对齐。<br>对于VDEQ模式，该地址指向32字节大小的反量化参数向量，其中每个元素大小为16bit（half）。<br>对于VDEQ8、VDEQ16模式，反量化参数向量中的每个元素大小都为64bit。搬运时会搬运blockCount个连续传输数据块，每个数据块的长度为blockLen。每个数据块对应一个128字节的反量化向量。对于同一个数据块，反量化参数向量中的16个元素会被连续复用。不同的数据块，对应不同的反量化参数向量，地址会相应的偏移12。例如：假设对应起始地址为A，第一个数据块的12反量化参数向量起始地址为A，第二个数据块的12反量化参数向量起始地址为A + 12。<br>同一个反量化参数向量的每一个元素的MCB标志位必须一致。</td></tr><tr><td>sidStoreMode</td><td>用于deqScale为DEQ8/VDEQ8时配置存储模式，控制反量化结果如何存储在dst地址中。配置效果参考<a href="#fig5416115192414">sidStoreMode配置示意图</a>。<br>  • 0：dst的数据存储在每个DataBlock的前半段，即每32字节的高16字节；<br>  • 1：dst的数据存储在每个DataBlock的后半段，即每32字节的低16字节；<br>  • 2：dst的数据存储在完整的DataBlock中，即整个32字节。</td></tr><tr><td>isRelu</td><td>配置是否可以随路做线性整流操作。配置deqValue的情况下，如果该参数被置为true，那么会刷新deqValue的ReLU标志位为1；如果被置为false，则不会做修改。配置deqTensorAddr的情况下，反量化参数向量元素中的ReLU标志位不生效，以isRelu为准。<br>仅配置isRelu，不配置量化参数，即deqValue配置为DEQ_NONE场景，支持src和dst的数据类型组合如下：{half，half}，{float，float}，{int32_t，int32_t}，{float，half}；同时配置isRelu和量化参数的场景，支持的数据类型组合参考<a href="#table168091348673">表7</a>。</td></tr><tr><td>padMode</td><td>预留参数，当前暂不支持。</td></tr></tbody></table><p><strong>表6</strong> 不同blockMode对应的参数单位（<a href="../../../../../guide/programming_guide/language_extension/simd_builtin_keywords.html">NPU架构版本2002</a>）<a id="table13396838183618"></a></p><table><thead><tr><th>blockMode</th><th>src</th><th>dst</th><th>数据类型</th><th>blockLen单位</th><th>srcStride单位</th><th>dstStride单位</th></tr></thead><tbody><tr><td>BLOCK_MODE_MATRIX</td><td>L0C Buffer（CO1）</td><td>UB（CO2）</td><td>half、int16_t、uint16_t</td><td>512B</td><td>512B</td><td>32B</td></tr><tr><td>BLOCK_MODE_MATRIX</td><td>L0C Buffer（CO1）</td><td>UB（CO2）</td><td>float、int32_t、uint32_t</td><td>1024B</td><td>1024B</td><td>32B</td></tr><tr><td>BLOCK_MODE_VECTOR</td><td>L0C Buffer（CO1）</td><td>UB（CO2）</td><td>half、int16_t、uint16_t</td><td>32B</td><td>512B</td><td>32B</td></tr><tr><td>BLOCK_MODE_VECTOR</td><td>L0C Buffer（CO1）</td><td>UB（CO2）</td><td>float、int32_t、uint32_t</td><td>64B</td><td>1024B</td><td>32B</td></tr></tbody></table><p><strong>表7</strong> deqScale参数列表（<a href="../../../../../guide/programming_guide/language_extension/simd_builtin_keywords.html">NPU架构版本2002</a>）<a id="table168091348673"></a></p><table><thead><tr><th>量化模式</th><th>src.dtype</th><th>dst.dtype</th><th>配合使用的参数</th></tr></thead><tbody><tr><td>DEQ</td><td>int32_t</td><td>half</td><td>deqValue中的变量M</td></tr><tr><td>DEQ</td><td>half</td><td>half</td><td>deqValue中的变量M</td></tr><tr><td>DEQ8</td><td>int32_t</td><td>int8_t</td><td>• deqValue<br>  •变量M<br>  •变量N<br>  • MCB标志位<br>  • Offset<br>  • Sign标志位<br>  • ReLU标志位<br>  • isRelu</td></tr><tr><td>DEQ8</td><td>int32_t</td><td>uint8_t</td><td>• deqValue<br>  •变量M<br>  •变量N<br>  • MCB标志位<br>  • Offset<br>  • Sign标志位<br>  • ReLU标志位<br>  • isRelu</td></tr><tr><td>DEQ16</td><td>int32_t</td><td>half</td><td>• deqValue<br>  •变量M<br>  •变量N<br>  • MCB标志位<br>  • ReLU标志位<br>  • isRelu</td></tr><tr><td>DEQ16</td><td>int32_t</td><td>int16_t</td><td>• deqValue<br>  •变量N<br>  • ReLU标志位<br>  • isRelu</td></tr><tr><td>VDEQ</td><td>int32_t</td><td>half</td><td>deqTensorAddr地址存储的反量化参数向量中的元素deqValue支持配置的参数分别对应DEQ/DEQ8/DEQ16的说明。<br>  • deqTensorAddr<br>  • DEQADDR<br>  • ReLU标志位<br>  • isRelu</td></tr><tr><td>VDEQ8</td><td>int32_t</td><td>int8_t</td><td>deqTensorAddr地址存储的反量化参数向量中的元素deqValue支持配置的参数分别对应DEQ/DEQ8/DEQ16的说明。<br>  • deqTensorAddr<br>  • DEQADDR<br>  • ReLU标志位<br>  • isRelu</td></tr><tr><td>VDEQ8</td><td>int32_t</td><td>uint8_t</td><td>deqTensorAddr地址存储的反量化参数向量中的元素deqValue支持配置的参数分别对应DEQ/DEQ8/DEQ16的说明。<br>  • deqTensorAddr<br>  • DEQADDR<br>  • ReLU标志位<br>  • isRelu</td></tr><tr><td>VDEQ16</td><td>int32_t</td><td>half</td><td>deqTensorAddr地址存储的反量化参数向量中的元素deqValue支持配置的参数分别对应DEQ/DEQ8/DEQ16的说明。<br>  • deqTensorAddr<br>  • DEQADDR<br>  • ReLU标志位<br>  • isRelu</td></tr><tr><td>VDEQ16</td><td>int32_t</td><td>int16_t</td><td>deqTensorAddr地址存储的反量化参数向量中的元素deqValue支持配置的参数分别对应DEQ/DEQ8/DEQ16的说明。<br>  • deqTensorAddr<br>  • DEQADDR<br>  • ReLU标志位<br>  • isRelu</td></tr></tbody></table><p><strong>表8</strong> deqValue配置方式（<a href="../../../../../guide/programming_guide/language_extension/simd_builtin_keywords.html">NPU架构版本2002</a>）<a id="table54451538192912"></a></p><table><thead><tr><th>模式</th><th>比特位数</th><th>变量名</th><th>作用介绍</th></tr></thead><tbody><tr><td>DEQ8、VDEQ8、DEQ16、VDEQ16</td><td>0~31</td><td>M</td><td>32位数视为float，作为反量化计算所需要乘的值。src为int32_t，dst为int16_t的场景下，变量M不生效。</td></tr><tr><td>DEQ8、VDEQ8、DEQ16、VDEQ16</td><td>32~35</td><td>N</td><td>4位比特位，表示范围为[1, 16]（b&#39;0000对应表示1，b&#39;1111对应表示16）。<br>当模式为DEQ8、VDEQ8时，MCB标志位置为1时，将输入的值进行右移N比特位。当模式为DEQ16、VDEQ16并且dst数据类型为int16_t时，直接进行N位的右移，不受MCB标志位控制。</td></tr><tr><td>DEQ8、VDEQ8、DEQ16、VDEQ16</td><td>36</td><td>MCB标志位</td><td>Mode Control Bit。如果置为0，输入的int32_t会被直接转换为float。如果置为1，输入的int32_t会先右移N比特位，转变成int16_t，然后转换为float。</td></tr><tr><td>DEQ8、VDEQ8、DEQ16、VDEQ16</td><td>37~45</td><td>Offset</td><td>9bit的整型数据，在进行反量化src * M的计算结果后与Offset进行相加。仅在DEQ8、VDEQ8模式中会用到。如果不使用offset，请置为0。</td></tr><tr><td>DEQ8、VDEQ8、DEQ16、VDEQ16</td><td>46</td><td>Sign标志位</td><td>如果置为1，表明反量化结果是signed(int8)；如果置为0，表明反量化结果是unsigned(uint8)。仅在DEQ8、VDEQ8模式中会用到。</td></tr><tr><td>DEQ8、VDEQ8、DEQ16、VDEQ16</td><td>47</td><td>ReLU标志位</td><td>如果置为1，对最终结果进行ReLU计算；如果置为0，不进行额外计算。<br>  •对于int32_t-&gt;int8_t，配置ReLU时，offset必须配置成-128；<br>  •对于int32_t-&gt;uint8_t，配置ReLU时，offset必须配置成0。</td></tr><tr><td>DEQ8、VDEQ8、DEQ16、VDEQ16</td><td>48~63</td><td>-</td><td>预留</td></tr><tr><td>DEQ、VDEQ</td><td>0 ~ 15</td><td>M</td><td>这16位数被视为half，作为反量化计算需要乘的值。</td></tr></tbody></table><p><strong>图2</strong> sidStoreMode配置示意图（<a href="../../../../../guide/programming_guide/language_extension/simd_builtin_keywords.html">NPU架构版本2002</a>）<a id="fig5416115192414"></a></p><p><img src="`+c+`" alt title="sidStoreMode配置示意图"></p></div><h2 id="数据类型">数据类型<a id="section8664371012"></a><a class="header-anchor" href="#数据类型">​</a></h2><div data-filter="950"><p>针对Ascend 950PR&amp;950DT系列产品，支持的数据类型组合如下：</p><table><thead><tr><th>源矩阵（L0C Buffer）</th><th>目的矩阵（UB）</th></tr></thead><tbody><tr><td>float</td><td>int8_t、uint8_t、hifloat8_t、fp8_e4m3fn_t、half、bfloat16_t、float。</td></tr><tr><td>int32_t</td><td>int8_t、uint8_t、half、bfloat16_t、int32_t。</td></tr></tbody></table></div><div data-filter="310p"><p>针对Atlas推理系列产品AI Core：</p><ul><li><p>源操作数和目的操作数的数据类型保持一致时，支持的数据类型为：half、float、int32_t、uint32_t。</p></li><li><p>源操作数和目的操作数的数据类型不一致时，支持情况见下表：</p><table><thead><tr><th>源操作数的数据类型</th><th>目的操作数的数据类型</th></tr></thead><tbody><tr><td>float</td><td>half</td></tr><tr><td>int32_t</td><td>int8_t、uint8_t、int16_t、half。</td></tr></tbody></table></li></ul></div><h2 id="返回值说明">返回值说明<span id="section16867144513189"></span><a class="header-anchor" href="#返回值说明">​</a></h2><p>无</p><h2 id="约束说明">约束说明<span id="section633mcpsimp"></span><a class="header-anchor" href="#约束说明">​</a></h2><div data-filter="950"><p>针对Ascend 950PR&amp;950DT系列产品，约束说明如下：</p><ul><li><p>源矩阵Nz格式地址要求64字节对齐，目的矩阵Nz格式地址需要满足32字节对齐。</p></li><li><p>当搬出的mSize、nSize或者ndNum中的任意一个值为0时，该指令不会被执行。ndNum=0时会报warning。</p></li><li><p>量化和ReLU参数不能为inf/nan和非规格化数。</p></li><li><p>目标数据不能有重叠。如果对目的地址有重叠写入，硬件不会报告任何警告和错误，也不保证重叠数据的写入顺序。</p></li><li><p>unitFlag特性开启需要配合Mmad同时开启。</p></li><li><p>dualDstCtl仅支持在普通搬运模式（Nz2Nz）或Nz2ND搬运场景下使用。</p></li><li><p>当启用Nz2DN且srcNzC0Stride不等于1时，不能同时开启unitFlag。</p></li><li><p>该接口仅适用于Mix算子场景，且仅支持Cube核数与Vector核数比例为1:2的配置。在该场景下，subBlockId仅支持取值0或1。</p></li><li><p>特殊值/边界值约束说明：</p><p>对于浮点类型inf/nan输入输出，可以通过CTRL寄存器（控制寄存器）的CTRL[48]比特位进行设置，控制浮点数量化搬出时的饱和模式，该模式由CTRL[48]直接决定；</p><p>对于fp8_e4m3fn_t类型，可以通过CTRL寄存器（控制寄存器）的CTRL[48]比特位进行更精细的设置；</p><ul><li><p>非饱和模式：CTRL[48]设置成1&#39;b1，inf/nan保持原输出。对于fp8_e4m3fn_t类型，若结果的绝对值为inf或大于fp8_e4m3fn_t的最大规格化值，则输出结果为nan。</p></li><li><p>饱和模式：CTRL[48]设置成1&#39;b0，inf输出会被饱和为±MAX， nan输出会被饱和为0。对于fp8_e4m3fn_t类型，当CTRL[50]设置成1&#39;b0时，nan被转换为零，当CTRL[50]设置成1&#39;b1时，nan保持不变，若结果的绝对值为inf或大于fp8_e4m3fn_t的最大规格化值，则结果为最大规格化值。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// 该模式由CTRL[48]直接决定，不受CTRL[60]限制。</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">SetCtrlSpr</span><span class="o">&lt;</span><span class="mi">48</span><span class="p">,</span><span class="w"> </span><span class="mi">48</span><span class="o">&gt;</span><span class="p">(</span><span class="mi">0</span><span class="p">);</span>
</code></pre></div></li></ul><p>对于整数类型只有饱和模式。 L0C Buffer到UB搬运接口的边界值汇总请见<a href="../../../../appendix/matrix_compute_move_out_interface_boundary_value_summary.html">矩阵计算搬出相关接口边界值汇总</a>。</p></li></ul></div><div data-filter="310p"><p>针对Atlas推理系列产品AI Core，约束说明如下：</p><ul><li>量化参数不能为inf/nan和非规格化数。</li><li>开发者需要保证DataCopyEnhancedParams中的isRelu参数配置和量化系数deqValue/量化参数向量deqTensorAddr的ReLU标志位配置一致：都开启或都不开启。</li><li>如果有随路精度转换，操作数的blockLen单位需要减半。</li></ul></div><h2 id="调用示例">调用示例<span id="section1491211256313"></span><a class="header-anchor" href="#调用示例">​</a></h2><div data-filter="950"><p>针对Ascend 950PR&amp;950DT系列产品，调用示例如下：</p><ul><li><p>输入A矩阵和B矩阵的数据类型为half，输出C矩阵为int8_t，不开启Nz2ND和Nz2DN的格式转换，不开启双目标模式，搬入默认的SUB BLOCK0，开启scalar量化：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">constexpr</span><span class="w"> </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">c0Size</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">32</span><span class="p">;</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">DataCopyCO12DstParams</span><span class="w"> </span><span class="n">dataCopyParams</span><span class="p">;</span>

<span class="n">dataCopyParams</span><span class="p">.</span><span class="n">dstStride</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">baseM</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">c0Size</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="n">outputType</span><span class="p">)</span><span class="w"> </span><span class="o">/</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">ONE_BLK_SIZE</span><span class="p">;</span>
<span class="n">dataCopyParams</span><span class="p">.</span><span class="n">mSize</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">baseM</span><span class="p">;</span>
<span class="n">dataCopyParams</span><span class="p">.</span><span class="n">srcStride</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">CeilAlign</span><span class="p">(</span><span class="n">baseM</span><span class="p">,</span><span class="w"> </span><span class="n">CUBE_BLOCK</span><span class="p">);</span>
<span class="n">dataCopyParams</span><span class="p">.</span><span class="n">nSize</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">baseN</span><span class="p">;</span>
<span class="n">dataCopyParams</span><span class="p">.</span><span class="n">quantPre</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">QuantMode_t</span><span class="o">::</span><span class="n">QF322B8_PRE</span><span class="p">;</span>

<span class="kt">uint64_t</span><span class="w"> </span><span class="n">deqScalar</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="k">static_cast</span><span class="o">&lt;</span><span class="kt">uint64_t</span><span class="o">&gt;</span><span class="p">(</span><span class="o">*</span><span class="k">reinterpret_cast</span><span class="o">&lt;</span><span class="kt">int32_t</span><span class="o">*&gt;</span><span class="p">(</span><span class="o">&amp;</span><span class="n">quantScalar</span><span class="p">));</span>
<span class="k">constexpr</span><span class="w"> </span><span class="kt">bool</span><span class="w"> </span><span class="n">sign</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="p">(</span><span class="n">AscendC</span><span class="o">::</span><span class="n">IsSameType</span><span class="o">&lt;</span><span class="n">outputType</span><span class="p">,</span><span class="w"> </span><span class="kt">int8_t</span><span class="o">&gt;::</span><span class="n">value</span><span class="p">)</span><span class="w"> </span><span class="o">?</span><span class="w"> </span><span class="nb">true</span><span class="w"> </span><span class="o">:</span><span class="w"> </span><span class="nb">false</span><span class="p">;</span>
<span class="n">deqScalar</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="p">(</span><span class="n">deqScalar</span><span class="w"> </span><span class="o">&amp;</span><span class="w"> </span><span class="o">~</span><span class="p">(</span><span class="k">static_cast</span><span class="o">&lt;</span><span class="kt">uint64_t</span><span class="o">&gt;</span><span class="p">(</span><span class="mi">1</span><span class="p">)</span><span class="w"> </span><span class="o">&lt;&lt;</span><span class="w"> </span><span class="mi">46</span><span class="p">))</span><span class="w"> </span><span class="o">|</span><span class="w"> </span><span class="p">(</span><span class="k">static_cast</span><span class="o">&lt;</span><span class="kt">uint64_t</span><span class="o">&gt;</span><span class="p">(</span><span class="n">sign</span><span class="p">)</span><span class="w"> </span><span class="o">&lt;&lt;</span><span class="w"> </span><span class="mi">46</span><span class="p">);</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">SetFixpipePreQuantFlag</span><span class="p">(</span><span class="n">deqScalar</span><span class="p">);</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">DataCopy</span><span class="p">(</span><span class="n">ubLocal</span><span class="p">,</span><span class="w"> </span><span class="n">c</span><span class="p">,</span><span class="w"> </span><span class="n">dataCopyParams</span><span class="p">);</span>
</code></pre></div></li></ul></div><div data-filter="310p"><p>针对Atlas推理系列产品AI Core，调用示例如下：</p><ul><li><p>Local Memory -&gt; Local Memory</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// srcLocal、dstLocal为half类型的LocalTensor</span>
<span class="c1">// 使用传入DataCopyParams参数的搬运接口，支持连续和非连续搬运</span>
<span class="n">DataCopyParams</span><span class="w"> </span><span class="n">intriParams</span><span class="p">;</span>
<span class="n">intriParams</span><span class="p">.</span><span class="n">blockCount</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">1</span><span class="p">;</span><span class="w"> </span><span class="c1">// 连续数据块个数为1</span>
<span class="n">intriParams</span><span class="p">.</span><span class="n">blockLen</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">512</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="n">half</span><span class="p">)</span><span class="w"> </span><span class="o">/</span><span class="w"> </span><span class="mi">32</span><span class="p">;</span><span class="w"> </span><span class="c1">// 连续数据块长度，单位为DataBlock，此处长度为512个half元素</span>
<span class="n">intriParams</span><span class="p">.</span><span class="n">srcGap</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w"> </span><span class="c1">// 源操作数做连续搬运</span>
<span class="n">intriParams</span><span class="p">.</span><span class="n">dstGap</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w"> </span><span class="c1">// 目的操作数连续排布</span>
<span class="n">DataCopyEnhancedParams</span><span class="w"> </span><span class="n">enhancedParams</span><span class="p">;</span>
<span class="n">enhancedParams</span><span class="p">.</span><span class="n">blockMode</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">BlockMode</span><span class="o">::</span><span class="n">BLOCK_MODE_MATRIX</span><span class="p">;</span><span class="w"> </span><span class="c1">// 传输单位为16*16的cube分形</span>
<span class="n">enhancedParams</span><span class="p">.</span><span class="n">deqScale</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">DeqScale</span><span class="o">::</span><span class="n">DEQ_NONE</span><span class="p">;</span><span class="w"> </span><span class="c1">// 不做量化</span>
<span class="n">enhancedParams</span><span class="p">.</span><span class="n">deqValue</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span>
<span class="n">enhancedParams</span><span class="p">.</span><span class="n">deqTensorAddr</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span>
<span class="n">enhancedParams</span><span class="p">.</span><span class="n">sidStoreMode</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w"> </span><span class="c1">// 仅deqScale为DEQ8/VDEQ8时生效</span>
<span class="n">enhancedParams</span><span class="p">.</span><span class="n">isRelu</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="nb">false</span><span class="p">;</span><span class="w"> </span><span class="c1">// 不支持ReLU</span>
<span class="n">enhancedParams</span><span class="p">.</span><span class="n">padMode</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">pad_t</span><span class="o">::</span><span class="n">PAD_NONE</span><span class="p">;</span><span class="w"> </span><span class="c1">// 预留参数</span>
<span class="c1">// 功能等同基础数据搬运</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">DataCopy</span><span class="p">(</span><span class="n">dstLocal</span><span class="p">,</span><span class="w"> </span><span class="n">srcLocal</span><span class="p">,</span><span class="w"> </span><span class="n">intriParams</span><span class="p">,</span><span class="w"> </span><span class="n">enhancedParams</span><span class="p">);</span>
</code></pre></div></li><li><p>Local Memory -&gt; Local Memory，源操作数与目的操作数类型不一致</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// 以下示例为L0C Buffer -&gt; UB通路的数据搬运，仅在Atlas推理系列产品AI Core场景下支持。srcLocal为int32_t类型的L0C Buffer上的LocalTensor，dstLocal为int8_t类型的UB上的LocalTensor</span>
<span class="c1">// 使用传入DataCopyParams参数的搬运接口，支持连续和非连续搬运</span>
<span class="n">DataCopyParams</span><span class="w"> </span><span class="n">intriParams</span><span class="p">;</span>
<span class="n">intriParams</span><span class="p">.</span><span class="n">blockCount</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">1</span><span class="p">;</span><span class="w"> </span><span class="c1">// 连续数据块个数为1</span>
<span class="n">intriParams</span><span class="p">.</span><span class="n">blockLen</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">512</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="n">half</span><span class="p">)</span><span class="w"> </span><span class="o">/</span><span class="w"> </span><span class="mi">32</span><span class="p">;</span><span class="w"> </span><span class="c1">// 连续数据块长度，单位为DataBlock，此处长度为512个half元素</span>
<span class="n">intriParams</span><span class="p">.</span><span class="n">srcGap</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w"> </span><span class="c1">// 源操作数做连续搬运</span>
<span class="n">intriParams</span><span class="p">.</span><span class="n">dstGap</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w"> </span><span class="c1">// 目的操作数连续排布</span>
<span class="n">DataCopyEnhancedParams</span><span class="w"> </span><span class="n">enhancedParams</span><span class="p">;</span>
<span class="n">enhancedParams</span><span class="p">.</span><span class="n">blockMode</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">BlockMode</span><span class="o">::</span><span class="n">BLOCK_MODE_MATRIX</span><span class="p">;</span><span class="w"> </span><span class="c1">// 传输单位为16*16的cube分形</span>
<span class="n">enhancedParams</span><span class="p">.</span><span class="n">deqScale</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">DeqScale</span><span class="o">::</span><span class="n">DEQ8</span><span class="p">;</span><span class="w"> </span><span class="c1">// int32_t -&gt; int8_t量化模式，配合deqValues使用</span>
<span class="n">enhancedParams</span><span class="p">.</span><span class="n">deqValue</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">70369809530880</span><span class="p">;</span><span class="w"> </span><span class="c1">// float 1 = uint64_t 1065353216, when s322s8 use 1065353216 | (1 &lt;&lt; 46)</span>
<span class="n">enhancedParams</span><span class="p">.</span><span class="n">deqTensorAddr</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w"> </span><span class="c1">// 仅VDEQ模式下使用</span>
<span class="n">enhancedParams</span><span class="p">.</span><span class="n">sidStoreMode</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">2</span><span class="p">;</span><span class="w"> </span><span class="c1">// dstLocal的数据存储在完整的DataBlock中</span>
<span class="n">enhancedParams</span><span class="p">.</span><span class="n">isRelu</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="nb">false</span><span class="p">;</span><span class="w"> </span><span class="c1">// 不支持ReLU</span>
<span class="n">enhancedParams</span><span class="p">.</span><span class="n">padMode</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">pad_t</span><span class="o">::</span><span class="n">PAD_NONE</span><span class="p">;</span><span class="w"> </span><span class="c1">// 预留参数</span>
<span class="c1">// 此时dstLocal = srcLocal</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">DataCopy</span><span class="p">(</span><span class="n">dstLocal</span><span class="p">,</span><span class="w"> </span><span class="n">srcLocal</span><span class="p">,</span><span class="w"> </span><span class="n">intriParams</span><span class="p">,</span><span class="w"> </span><span class="n">enhancedParams</span><span class="p">);</span>
</code></pre></div></li></ul></div></article></div>`,1)])])}const m=n(e,[["render",d]]);export{f as __pageData,m as default};
